        return [(string) $bill->id => [
            'id' => $bill->id,
            'student' => $bill->pendaftar?->biodata?->full_name ?? $bill->pendaftar?->user?->name ?? 'Peserta',
            'registration' => $bill->pendaftar?->registration_number ?? '-',
            'billType' => $bill->jenisTagihan?->name ?? 'Tagihan SPMB',
            'total' => (float) $bill->total_amount, 'paid' => (float) $bill->paid_amount, 'remaining' => (float) $bill->remaining_amount,
            'invoiceUrl' => route($routePrefix.'tagihan.invoice', $bill),
            'canRecord' => true,
            'online' => null,
            'pending' => null,
            'transactions' => $bill->transaksi->map(fn ($transaction) => [
                'date' => $transaction->payment_date ? \Illuminate\Support\Carbon::parse($transaction->payment_date)->format('d M Y, H:i') : '-',
                'amount' => (float) $transaction->amount,
                'method' => $transaction->payment_method === 'cash' ? 'Tunai' : 'Transfer',
                'reference' => $transaction->reference_number ?? $transaction->transaction_number ?? '-',
                'status' => $transaction->treasurer_received_at ? 'Diterima keuangan' : (match ($transaction->status) { 'verified' => 'Disetujui — menunggu penerimaan', 'rejected' => 'Ditolak', default => 'Menunggu persetujuan' }),
                'approvedBy' => $transaction->verifier?->name,
                'approvedLabel' => $transaction->treasurer_received_at && $transaction->verified_by == $transaction->treasurer_received_by ? 'Dicatat langsung:' : 'Disetujui:',
                'approvedAt' => $transaction->verified_at ? \Illuminate\Support\Carbon::parse($transaction->verified_at)->format('d M Y, H:i') : null,
                'receivedBy' => $transaction->treasurerReceiver?->name,
                'receivedAt' => $transaction->treasurer_received_at ? \Illuminate\Support\Carbon::parse($transaction->treasurer_received_at)->format('d M Y, H:i') : null,
                'received' => (bool) $transaction->treasurer_received_at,
                'items' => collect($transaction->selected_items ?? [])->values(),
                'selectedItems' => collect($transaction->selected_items ?? [])->pluck('name')->values(),
                'receiveUrl' => $transaction->status === 'verified' && ! $transaction->treasurer_received_at ? route($routePrefix.'pembayaran.receive', $transaction) : null,
                'receiptUrl' => $transaction->status === 'verified' && (! str_contains(strtolower((string) $bill->jenisTagihan?->name), 'daftar ulang') || $transaction->treasurer_received_at) ? route($routePrefix.'pembayaran.receipt', $transaction) : null,
            ])->values(),
        ]];
    });
    $paymentInputBills = $inputBills->mapWithKeys(function ($bill) {
        $quote = \App\Support\PaymentQuote::forBill($bill);
        $typeName = strtolower((string) $bill->jenisTagihan?->name);
        $remaining = $quote['requires_selection'] ? (float) collect($quote['items'])->sum('amount') : (float) $quote['amount'];
        return [(string) $bill->id => ['id' => $bill->id, 'student' => $bill->pendaftar?->biodata?->full_name ?? $bill->pendaftar?->user?->name ?? 'Peserta', 'type' => $bill->jenisTagihan?->name ?? 'Tagihan SPMB', 'items' => $quote['items'], 'remaining' => (int) $remaining, 'is_registration_fee' => str_contains($typeName, 'formulir') || str_contains($typeName, 'pendaftaran'), 'is_re_registration_fee' => str_contains($typeName, 'daftar ulang') || str_contains($typeName, 'du')]];
